package check

import (
	"fmt"
	"strings"

	"ergo.local/prototype/internal/sketch/syntax"
)

// Checked Ergo C bindings (`// ergo:bind c ...`, CFFI-2).
//
// A binding file generated by `ergo bind c` carries:
//   - a provenance header:
//       // ergo:bind c <import_path> <header_sha256> <contract_sha256> <platforms...>
//   - `// ergo:cdata` above every flat C struct type;
//   - `implements Closer` + `Close()` on every destroyable opaque handle;
//   - `needs go.Foreign` on every C-bound function and method.
//
// The checker verifies every invariant fail-closed as S108 at import/use before
// any lowering:
//   1. Header/contract SHA-256 stamps and import path match (tamper fail-closed).
//   2. Every `// ergo:cdata` type and every C-bound value/buffer parameter or
//      result is recursively pointer-free at arbitrary nesting depth (defeating
//      cgo's depth-2 cutoff).
//   3. Every C-bound function/method requires `go.Foreign` in its needs row.

const (
	cBindHeaderPrefix = "// ergo:bind c "
	cBindGenPrefix    = "// Code generated by ergo bind c"
	cDataMarker       = "// ergo:cdata"
)

// looksLikeCBind reports whether h's source carries any C-binding provenance
// or C-data marker, so tampered or incomplete C bindings always enter
// fail-closed verification.
func (h *hostPkg) looksLikeCBind() bool {
	if h == nil {
		return false
	}
	return strings.Contains(h.src, cBindHeaderPrefix) ||
		strings.Contains(h.src, cBindGenPrefix) ||
		strings.Contains(h.src, cDataMarker)
}

// loadCBind reads C-binding provenance and `// ergo:cdata` markers from f.
func (h *hostPkg) loadCBind(f *syntax.File) {
	if !h.looksLikeCBind() {
		return
	}
	h.cBind = true
	h.verifyCBindHeader(f)

	cdataLines := map[int]bool{}
	for _, g := range f.Comments {
		for _, cm := range g.List {
			if strings.TrimSpace(cm.Text) == cDataMarker {
				line, _ := f.Position(cm.Pos())
				cdataLines[line] = true
			}
		}
	}
	if len(cdataLines) > 0 {
		h.cdata = map[*TypeName]bool{}
		for _, tn := range h.c.pkg.Types {
			if tn.Decl == nil {
				continue
			}
			line, _ := f.Position(tn.Decl.Pos())
			if cdataLines[line-1] {
				h.cdata[tn] = true
			}
		}
	}
}

func isSHA256Hex(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if !((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f')) {
			return false
		}
	}
	return true
}

func isPlatformToken(s string) bool {
	goos, goarch, ok := strings.Cut(s, "/")
	return ok && goos != "" && goarch != "" && !strings.Contains(goarch, "/")
}

// verifyCBindHeader validates the `// ergo:bind c` provenance line and its
// header/contract SHA-256 stamps.
func (h *hostPkg) verifyCBindHeader(f *syntax.File) {
	var headerLine string
	for _, line := range strings.SplitN(h.src, "\n", 6) {
		if rest, ok := strings.CutPrefix(line, cBindHeaderPrefix); ok {
			headerLine = strings.TrimSpace(rest)
			break
		}
	}
	if headerLine == "" {
		h.c.errorf(f, CodeType, "missing %q provenance header", strings.TrimSpace(cBindHeaderPrefix))
		return
	}
	fields := strings.Fields(headerLine)
	if len(fields) < 4 {
		h.c.errorf(f, CodeType, "malformed // ergo:bind c header: want `<import_path> <header_sha256> <contract_sha256> <platforms...>`")
		return
	}
	importPath, headerSHA, contractSHA, platforms := fields[0], fields[1], fields[2], fields[3:]
	if importPath != h.c.pkg.Path {
		h.c.errorf(f, CodeType, "// ergo:bind c import path %q does not match %q", importPath, h.c.pkg.Path)
		return
	}
	if !isSHA256Hex(headerSHA) {
		h.c.errorf(f, CodeType, "// ergo:bind c header sha256 %q is not a valid 64-hex SHA-256 digest", headerSHA)
		return
	}
	if !isSHA256Hex(contractSHA) {
		h.c.errorf(f, CodeType, "// ergo:bind c contract sha256 %q is not a valid 64-hex SHA-256 digest", contractSHA)
		return
	}
	for _, p := range platforms {
		if !isPlatformToken(p) {
			h.c.errorf(f, CodeType, "// ergo:bind c platform %q is not <goos>/<goarch>", p)
			return
		}
	}
	h.cHeaderSHA = headerSHA
	h.cContractSHA = contractSHA
	if h.set != nil && h.set.VerifyCStamp != nil {
		if why := h.set.VerifyCStamp(importPath, headerSHA, contractSHA); why != "" {
			h.c.errorf(f, CodeType, "C binding stamp mismatch: %s", why)
		}
	}
}

// verifyCBindAll resolves and validates every type and function of a C binding.
func (h *hostPkg) verifyCBindAll() {
	if h == nil || !h.cBind {
		return
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	h.verifyCBindAllLocked()
}

func (h *hostPkg) verifyCBindAllLocked() {
	if h == nil || !h.cBind || h.cChecked {
		return
	}
	h.cChecked = true
	if h.fi != nil {
		saved := h.c.cur
		h.c.cur = h.fi
		defer func() { h.c.cur = saved }()
	}
	// 1. Verify every `// ergo:cdata` type is deeply pointer-free at arbitrary depth.
	for _, tn := range h.c.pkg.Types {
		n, _ := tn.Type.(*Named)
		if n != nil {
			h.c.resolveNamedLocked(n)
		}
		if h.cdata[tn] {
			if ok, why := h.c.isCData(tn.Type); !ok {
				h.c.errorf(tn.Decl.Name, CodeType, "C data type %s is not pointer-free: %s", tn.Name, why)
			}
		}
	}
	// 2. Verify every C-bound function and method carries `needs go.Foreign` and
	//    only crosses the boundary with C-safe types.
	for _, fn := range h.c.pkg.Funcs {
		h.c.funcSigLocked(fn)
		h.verifyCBindFunc(fn, false)
	}
	for _, tn := range h.c.pkg.Types {
		n, _ := tn.Type.(*Named)
		if n == nil {
			continue
		}
		for _, m := range n.mlist {
			h.c.funcSigLocked(m)
			h.verifyCBindFunc(m, true)
		}
	}
}

func hasGoForeign(sig *Signature) bool {
	if sig == nil || sig.Uses == nil {
		return false
	}
	gf := goForeign()
	for _, e := range sig.Uses.Elems() {
		if e == gf {
			return true
		}
	}
	return false
}

func (h *hostPkg) verifyCBindFunc(fn *Func, isMethod bool) {
	if fn == nil || fn.Sig == nil || fn.Decl == nil {
		return
	}
	if !hasGoForeign(fn.Sig) {
		h.c.errorf(fn.Decl.Name, CodeType, "C binding %s must declare needs go.Foreign", fn.Name)
	}
	// Package loader (`Load(path string)`), callback counter (`LiveCallbacks()`),
	// error formatting (`Status.Error()`), handle Close, and record marker
	// methods have fixed Go interop shapes.
	if !isMethod && (fn.Name == "Load" || fn.Name == "LiveCallbacks") {
		return
	}
	if isMethod && (fn.Name == "Error" || fn.Name == "Close" || strings.HasPrefix(fn.Name, "Is")) {
		return
	}
	h.verifyCBindScoped(fn)
	for i, p := range fn.Sig.Params {
		if cbSig, ok := under0(p.Type).(*Signature); ok {
			h.verifyCBindCallbackParam(fn, i, p, cbSig)
			continue
		}
		if ok, why := h.c.cBindBoundaryType(p.Type, true); !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "C binding %s parameter %s (%s) is not C-safe: %s", fn.Name, p.Name, p.Type, why)
		}
	}
	for _, r := range fn.Sig.Results {
		if tup, ok := r.(*Tuple); ok {
			for _, elem := range tup.Types {
				if ok, why := h.c.cBindBoundaryType(elem, false); !ok {
					h.c.errorf(fn.Decl.Name, CodeType, "C binding %s result (%s) is not C-safe: %s", fn.Name, elem, why)
				}
			}
			continue
		}
		if ok, why := h.c.cBindBoundaryType(r, false); !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "C binding %s result (%s) is not C-safe: %s", fn.Name, r, why)
		}
	}
}

// isOpaqueCHandle reports a host struct with zero fields (an opaque C handle
// such as Context) belonging to a C binding.
func isOpaqueCHandle(t Type) bool {
	n, ok := t.(*Named)
	if !ok || n.Obj == nil || n.Obj.Pkg == nil {
		return false
	}
	h := hostOf(n.Obj.Pkg)
	if h == nil || !h.cBind {
		return false
	}
	st, ok := under(n).(*Struct)
	return ok && len(st.Fields) == 0 && !h.cdata[n.Obj]
}

// isCRecordInterface reports a Go interface declared in a C binding (e.g.,
// ShapeHeaderRecord), verifying that every struct in the binding implementing
// its marker method is CData.
func (c *checker) isCRecordInterface(t Type) bool {
	n, ok := t.(*Named)
	if !ok || n.Obj == nil || n.Obj.Pkg == nil {
		return false
	}
	h := hostOf(n.Obj.Pkg)
	if h == nil || !h.cBind {
		return false
	}
	it, ok := under(n).(*Interface)
	if !ok || len(it.Methods) == 0 {
		return false
	}
	marker := it.Methods[0].Name
	if !strings.HasPrefix(marker, "Is") {
		return false
	}
	for _, tn := range n.Obj.Pkg.Types {
		cn, _ := tn.Type.(*Named)
		if cn == nil || cn.method(marker) == nil {
			continue
		}
		if ok, _ := c.isCData(cn); !ok {
			return false
		}
	}
	return true
}

// cBindBoundaryType reports whether t is a valid parameter or result type for
// a C-bound function: deeply pointer-free CData, a slice of CData (buffer),
// an opaque C handle (*H or go.Ref[H]), an optional pointer to CData
// (Option[go.Ref[T]]), or a C record interface whose kinds are CData.
func (c *checker) cBindBoundaryType(t Type, param bool) (bool, string) {
	if ok, _ := c.isCData(t); ok {
		return true, ""
	}
	// Buffer slice: []CData (elements must be deeply pointer-free CData).
	if sl, ok := t.(*Slice); ok {
		return c.isCData(sl.Elem)
	}
	// Opaque handle borrow (*Handle) on parameters.
	if ptr, ok := t.(*Pointer); ok && param {
		if isOpaqueCHandle(ptr.Elem) {
			return true, ""
		}
		return false, fmt.Sprintf("pointer to non-handle %s", ptr.Elem)
	}
	// Opaque handle reference (go.Ref[Handle]) on results or owned params.
	if elem := refElem(t); elem != nil {
		if isOpaqueCHandle(elem) {
			return true, ""
		}
		return false, fmt.Sprintf("go.Ref[%s] is not an opaque C handle", elem)
	}
	// Optional CData value: Option[go.Ref[CData]].
	if n, ok := t.(*Named); ok && n.Orig != nil && len(n.TArgs) == 1 {
		if opt := PreludeType("Option"); opt != nil && n.Orig.Obj == opt.Obj {
			if elem := refElem(n.TArgs[0]); elem != nil {
				return c.isCData(elem)
			}
		}
	}
	// Record-kind interface (e.g. ShapeHeaderRecord).
	if param && c.isCRecordInterface(t) {
		return true, ""
	}
	return c.isCData(t)
}

// cBindLentParam reports whether a non-`own` parameter of type t in a
// `// ergo:bind c` function is borrowed rather than taken: opaque C handle
// borrows (`*Context`) and C record interfaces (`ShapeHeaderRecord`). Destroy
// functions explicitly write `own *Context`, which puts them in sig.Takes
// before hostClauses runs.
func (c *checker) cBindLentParam(t Type) bool {
	if ptr, ok := t.(*Pointer); ok && isOpaqueCHandle(ptr.Elem) {
		return true
	}
	return c.isCRecordInterface(t)
}

// IsCData reports whether t is deeply pointer-free C data at arbitrary nesting
// depth: booleans, fixed/machine integers, floats, fixed arrays of CData, and
// records/structs/tuples whose fields are all CData (no Go strings, slices,
// maps, pointers, go.Ref, interfaces, functions, or tagged unions at any depth).
func IsCData(t Type) (bool, string) {
	var c checker
	return c.isCData(t)
}

func (c *checker) isCData(t Type) (bool, string) {
	return c.isCDataDepth(t, 0, map[Type]bool{})
}

func (c *checker) isCDataDepth(t Type, depth int, seen map[Type]bool) (bool, string) {
	if depth < 0 {
		return true, ""
	}
	if t == nil {
		return false, "nil type"
	}
	switch t := t.(type) {
	case *Basic:
		switch t.Kind {
		case Bool, Int, Int8, Int16, Int32, Int64, Uint, Uint8, Uint16, Uint32, Uint64, Float32, Float64:
			return true, ""
		case String:
			return false, "contains Go string (pointer + length)"
		case Duration:
			return false, "contains Go Duration"
		default:
			return false, fmt.Sprintf("non-C basic type %s", t)
		}
	case *Array:
		ok, why := c.isCDataDepth(t.Elem, depth+1, seen)
		if !ok {
			return false, fmt.Sprintf("[%d]%s: %s", t.Len, t.Elem, why)
		}
		return true, ""
	case *Struct:
		for _, f := range t.Fields {
			ok, why := c.isCDataDepth(f.Type, depth+1, seen)
			if !ok {
				return false, fmt.Sprintf("field %s (%s): %s", f.Name, f.Type, why)
			}
		}
		return true, ""
	case *Tuple:
		for i, elem := range t.Types {
			ok, why := c.isCDataDepth(elem, depth+1, seen)
			if !ok {
				return false, fmt.Sprintf("tuple element %d (%s): %s", i, elem, why)
			}
		}
		return true, ""
	case *Named:
		if refElem(t) != nil {
			return false, fmt.Sprintf("contains %s (Go pointer reference)", t)
		}
		if IsGoError(t) {
			return false, "contains go.Error interface"
		}
		if IsGoAny(t) {
			return false, "contains go.Any interface"
		}
		if seen[t] {
			return false, fmt.Sprintf("recursive type cycle through %s", t)
		}
		seen[t] = true
		defer delete(seen, t)
		u := under(t)
		if u == nil || u == t {
			return false, fmt.Sprintf("unresolved named type %s", t)
		}
		ok, why := c.isCDataDepth(u, depth+1, seen)
		if !ok {
			return false, fmt.Sprintf("%s: %s", t, why)
		}
		return true, ""
	case *Slice:
		return false, fmt.Sprintf("contains Go slice %s", t)
	case *Map:
		return false, fmt.Sprintf("contains Go map %s", t)
	case *Pointer:
		return false, fmt.Sprintf("contains Go pointer %s", t)
	case *Signature:
		return false, fmt.Sprintf("contains Go function value %s", t)
	case *Interface:
		return false, fmt.Sprintf("contains Go interface %s", t)
	case *Union:
		return false, fmt.Sprintf("contains tagged union %s", t)
	case *TypeParam:
		return false, fmt.Sprintf("contains uninstantiated type parameter %s", t)
	default:
		return false, fmt.Sprintf("unsupported non-C type %s", t)
	}
}
